tool.command:
mkdir -p run && cd run &&
cp '$d_file' job.d &&
cp '$bnd_file' job.bnd &&
cp '$fix_file' job.fix &&
cp '$dat_file' job.dat &&
cp '$mat_file' job.mat &&
mpirun -np \${GALAXY_SLOTS:-1} p124 job 2>&1;
RC=\$?;
if [ -f job.res ]; then mv job.res '$output_res'; else echo "Solver produced no .res output (exit code \${RC})" > '$output_res'; fi;
if ls job.ensi.* 1>/dev/null 2>&1; then tar czf '$output_ensi' job.ensi.*; else tar czf '$output_ensi' --files-from /dev/null; fi;
exit \${RC}
